class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is CameraLens) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    }    else if (value is FlashMode) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    }    else if (value is CaptureAspectRatio) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    }    else if (value is PreviewQuality) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    }    else if (value is MultiFacePolicy) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    }    else if (value is EngineErrorCode) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    }    else if (value is EngineConfig) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is PreviewDescriptor) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is BeautyParameters) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is ImageProcessingRequest) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is ImageProcessingResult) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is CameraCapabilities) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is PhotoCaptureResult) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is FaceTrackingStatus) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is PerformanceSample) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is EngineError) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : CameraLens.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : FlashMode.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : CaptureAspectRatio.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : PreviewQuality.values[value];
      case 133:
        final value = readValue(buffer) as int?;
        return value == null ? null : MultiFacePolicy.values[value];
      case 134:
        final value = readValue(buffer) as int?;
        return value == null ? null : EngineErrorCode.values[value];
      case 135:
        return EngineConfig.decode(readValue(buffer)!);
      case 136:
        return PreviewDescriptor.decode(readValue(buffer)!);
      case 137:
        return BeautyParameters.decode(readValue(buffer)!);
      case 138:
        return ImageProcessingRequest.decode(readValue(buffer)!);
      case 139:
        return ImageProcessingResult.decode(readValue(buffer)!);
      case 140:
        return CameraCapabilities.decode(readValue(buffer)!);
      case 141:
        return PhotoCaptureResult.decode(readValue(buffer)!);
      case 142:
        return FaceTrackingStatus.decode(readValue(buffer)!);
      case 143:
        return PerformanceSample.decode(readValue(buffer)!);
      case 144:
        return EngineError.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
